using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;
internal static class TestDockTrash {
 static int checks;static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static int Main(string[] args){try{
  string root=args[0];Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"pins.json"),"[]");var backend=new DockBackend(root);var icons=typeof(DockBackend).GetMethod("TrashIcon",BindingFlags.Instance|BindingFlags.NonPublic);string empty=(string)icons.Invoke(backend,new object[]{false}),full=(string)icons.Invoke(backend,new object[]{true});using(var a=Image.FromFile(empty))using(var b=Image.FromFile(full))Check(a.Width>=32&&b.Width>=32&&!File.ReadAllBytes(empty).SequenceEqual(File.ReadAllBytes(full)),"native empty and full Recycle Bin icons are distinct valid images");
  Check(DockBackend.RecycleCount().HasValue,"Windows Recycle Bin count can be read without changing its contents");var trash=DockBackend.TrashEntry(empty,0);Check(trash.system&&!trash.pinned&&trash.windows.Count==0&&trash.name.EndsWith(" · 空"),"empty bin is a fixed system utility without a running-app dot");Check(DockBackend.TrashEntry(full,12).name.EndsWith("12 项"),"full bin label reflects its item count");
  var apps=new List<DockEntry>{DockBackend.WorkspaceEntry("grid")};for(int i=0;i<35;i++)apps.Add(new DockEntry{id="p"+i,name="App "+i,pinned=true,windows=new List<DockWindow>{new DockWindow{handle=i+1}}});apps.Insert(5,trash);var visible=DockBackend.DisplayEntries(apps,"more");Check(visible.Count==32&&visible[0].id=="workspace"&&visible.Last().id=="trash","overflow always preserves application center first and trash last");Check(visible[30].name=="更多应用 · 6"&&visible[30].windows.Count==6,"overflow keeps every displaced application and window");Check(visible.Take(30).Select(e=>e.id).SequenceEqual(apps.Where(e=>e.id!="trash").Take(30).Select(e=>e.id)),"fixed apps retain their original order");
  apps.Add(visible[30]);var again=DockBackend.DisplayEntries(apps,"more");Check(again.Count==32&&again.Count(e=>e.id=="r2147483647")==1&&again[30].windows.Count==6,"drag snapshots do not duplicate an existing overflow entry");
  var small=DockBackend.DisplayEntries(new List<DockEntry>{trash,DockBackend.WorkspaceEntry("grid"),new DockEntry{id="r1",name="Running"}},"more");Check(small.Last().id=="trash"&&small[1].id=="r1","running applications stay before the fixed rightmost bin");string saved=File.ReadAllText(Path.Combine(root,"pins.json"));DockBackend.Unpin(root,"trash");DockBackend.Move(root,"trash","workspace");Check(File.ReadAllText(Path.Combine(root,"pins.json"))==saved,"trash cannot alter the user's pinned application list");
  var ordered=new List<DockEntry>{DockBackend.WorkspaceEntry("grid"),new DockEntry{id="p1",pinned=true},new DockEntry{id="p2",pinned=true},new DockEntry{id="r1"},trash};int slot;Check(DockBackend.BeforeAt(ordered,"p2",97,60,1,out slot)==""&&slot==2,"pin reordering follows the shifted centers when trash adds a second separator");
  Console.WriteLine("Completed "+checks+" focused Recycle Bin checks.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
